export interface ConnectorConfig {
  /** Pipedrive API token from environment variable PIPEDRIVE_API_TOKEN */
  pipedriveApiToken: string
  /** Typeform field ID for the respondent's full name */
  nameFieldId?: string
  /** Typeform field ID for the respondent's email */
  emailFieldId?: string
  /** Typeform field ID for the company/organization name */
  companyFieldId?: string
  /** Typeform field ID for the project description (deal title) */
  projectFieldId?: string
  /** Typeform field ID for phone number (optional) */
  phoneFieldId?: string
  /** Injected fetch for testing */
  fetch?: typeof fetch
}

export interface TypeformWebhookPayload {
  event_id: string
  event_type: string
  form_response: {
    form_id: string
    token: string
    submitted_at: string
    answers: Array<{
      type: string
      text?: string
      email?: string
      field: {
        id: string
        type: string
      }
    }>
  }
}

export interface HandleResult {
  organizationId: number
  personId: number
  dealId: number
}

function getAnswer(answers: TypeformWebhookPayload['form_response']['answers'], fieldId: string): string | undefined {
  const answer = answers.find((a) => a.field.id === fieldId)
  return answer?.text ?? answer?.email
}

function requireField(value: string | undefined, fieldName: string): string {
  if (!value || !value.trim()) {
    throw new Error(`Required field '${fieldName}' is missing or empty in Typeform response`)
  }
  return value.trim()
}

async function pipedrivePost<T>(
  url: string,
  body: unknown,
  token: string,
  fetchFn: typeof fetch
): Promise<T> {
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    const text = await response.text().catch(() => '')
    throw new Error(`Pipedrive API error: ${response.status} ${response.statusText} for ${url} - ${text}`)
  }

  return response.json() as Promise<T>
}

export async function handle(
  payload: TypeformWebhookPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  if (payload.event_type !== 'form_response') {
    throw new Error(`Unsupported event type: ${payload.event_type}. Expected 'form_response'`)
  }

  const answers = payload.form_response.answers

  const nameFieldId = config.nameFieldId ?? 'JwWggjAKtOkA'
  const emailFieldId = config.emailFieldId ?? 'SMEUb7VJz92Q'
  const companyFieldId = config.companyFieldId ?? 'some_company_field_id'
  const projectFieldId = config.projectFieldId ?? 'some_project_question_id'
  const phoneFieldId = config.phoneFieldId

  const name = requireField(getAnswer(answers, nameFieldId), 'name')
  const email = requireField(getAnswer(answers, emailFieldId), 'email')
  const company = getAnswer(answers, companyFieldId)?.trim()
  const project = getAnswer(answers, projectFieldId)?.trim()
  const phone = phoneFieldId ? getAnswer(answers, phoneFieldId)?.trim() : undefined

  const orgName = company || name

  const orgResponse = await pipedrivePost<{ success: boolean; data: { id: number; name: string } }>(
    'https://api.pipedrive.com/v2/organizations',
    { name: orgName },
    config.pipedriveApiToken,
    fetchFn
  )
  const organizationId = orgResponse.data.id

  const personResponse = await pipedrivePost<{ success: boolean; data: { id: number; name: string; org_id: number } }>(
    'https://api.pipedrive.com/v2/persons',
    {
      name,
      email: [email],
      org_id: organizationId,
      ...(phone ? { phone: [{ value: phone, primary: true }] } : {}),
    },
    config.pipedriveApiToken,
    fetchFn
  )
  const personId = personResponse.data.id

  const dealTitle = project || `Deal for ${name}`

  const dealResponse = await pipedrivePost<{ success: boolean; data: { id: number; title: string; person_id: number } }>(
    'https://api.pipedrive.com/v2/deals',
    {
      title: dealTitle,
      person_id: personId,
    },
    config.pipedriveApiToken,
    fetchFn
  )
  const dealId = dealResponse.data.id

  return { organizationId, personId, dealId }
}

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, TypeformWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      pipedriveApiToken: 'test-token',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TypeformWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result).toEqual({ organizationId: 12345, personId: 67890, dealId: 54321 })
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let basePayload: TypeformWebhookPayload

  beforeEach(() => {
    baseConfig = {
      pipedriveApiToken: 'test-api-token',
      nameFieldId: 'JwWggjAKtOkA',
      emailFieldId: 'SMEUb7VJz92Q',
      companyFieldId: 'some_company_field_id',
      projectFieldId: 'some_project_question_id',
    }
    basePayload = {
      event_id: 'evt-1',
      event_type: 'form_response',
      form_response: {
        form_id: 'form-1',
        token: 'token-1',
        submitted_at: '2024-01-15T10:00:00Z',
        answers: [
          { type: 'text', text: 'John Doe', field: { id: 'JwWggjAKtOkA', type: 'short_text' } },
          { type: 'email', email: 'john@example.com', field: { id: 'SMEUb7VJz92Q', type: 'email' } },
          { type: 'text', text: 'Acme Inc', field: { id: 'some_company_field_id', type: 'short_text' } },
          { type: 'text', text: 'Build a mobile app', field: { id: 'some_project_question_id', type: 'short_text' } },
        ],
      },
    }
  })

  it('creates organization, person, and deal on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ success: true, data: { id: 111, name: 'Acme Inc' } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ success: true, data: { id: 222, name: 'John Doe', org_id: 111 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ success: true, data: { id: 333, title: 'Build a mobile app', person_id: 222 } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const result = await handle(basePayload, { ...baseConfig, fetch })

    expect(result).toEqual({ organizationId: 111, personId: 222, dealId: 333 })
    expect(calls).toHaveLength(3)

    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://api.pipedrive.com/v2/organizations')
    expect(calls[0].json).toEqual({ name: 'Acme Inc' })
    expect(calls[0].headers.get('authorization')).toBe('Bearer test-api-token')

    expect(calls[1].method).toBe('POST')
    expect(calls[1].url).toBe('https://api.pipedrive.com/v2/persons')
    expect(calls[1].json).toEqual({ name: 'John Doe', email: ['john@example.com'], org_id: 111 })
    expect(calls[1].headers.get('authorization')).toBe('Bearer test-api-token')

    expect(calls[2].method).toBe('POST')
    expect(calls[2].url).toBe('https://api.pipedrive.com/v2/deals')
    expect(calls[2].json).toEqual({ title: 'Build a mobile app', person_id: 222 })
    expect(calls[2].headers.get('authorization')).toBe('Bearer test-api-token')
  })

  it('uses name as organization name when company field is missing', async () => {
    const payload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: basePayload.form_response.answers.filter((a) => a.field.id !== 'some_company_field_id'),
      },
    }

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ success: true, data: { id: 111, name: 'John Doe' } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ success: true, data: { id: 222, name: 'John Doe', org_id: 111 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ success: true, data: { id: 333, title: 'Build a mobile app', person_id: 222 } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const result = await handle(payload, { ...baseConfig, fetch })
    expect(result.organizationId).toBe(111)
    expect(calls[0].json).toEqual({ name: 'John Doe' })
  })

  it('includes phone when phoneFieldId is configured and present', async () => {
    const config = { ...baseConfig, phoneFieldId: 'phone_field_id' }
    const payload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: [
          ...basePayload.form_response.answers,
          { type: 'text', text: '+1-555-123-4567', field: { id: 'phone_field_id', type: 'phone' } },
        ],
      },
    }

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ success: true, data: { id: 111, name: 'Acme Inc' } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ success: true, data: { id: 222, name: 'John Doe', org_id: 111 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ success: true, data: { id: 333, title: 'Build a mobile app', person_id: 222 } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    await handle(payload, { ...config, fetch })
    expect(calls[1].json).toEqual({
      name: 'John Doe',
      email: ['john@example.com'],
      org_id: 111,
      phone: [{ value: '+1-555-123-4567', primary: true }],
    })
  })

  it('throws when name field is missing', async () => {
    const payload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: basePayload.form_response.answers.filter((a) => a.field.id !== 'JwWggjAKtOkA'),
      },
    }

    const { fetch } = fakeFetch(() => jsonResponse({}, 201))
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      "Required field 'name' is missing or empty in Typeform response"
    )
  })

  it('throws when email field is missing', async () => {
    const payload = {
      ...basePayload,
      form_response: {
        ...basePayload.form_response,
        answers: basePayload.form_response.answers.filter((a) => a.field.id !== 'SMEUb7VJz92Q'),
      },
    }

    const { fetch } = fakeFetch(() => jsonResponse({}, 201))
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      "Required field 'email' is missing or empty in Typeform response"
    )
  })

  it('throws on non-2xx response from organizations endpoint', async () => {
    const { fetch } = fakeFetch((req) =>
      req.url === 'https://api.pipedrive.com/v2/organizations'
        ? jsonResponse({ error: 'unauthorized' }, 401)
        : jsonResponse({}, 201)
    )

    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Pipedrive API error: 401 Unauthorized for https://api.pipedrive.com/v2/organizations'
    )
  })

  it('throws on non-2xx response from persons endpoint', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ success: true, data: { id: 111, name: 'Acme Inc' } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ error: 'forbidden' }, 403)
      }
      return jsonResponse({}, 201)
    })

    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Pipedrive API error: 403 Forbidden for https://api.pipedrive.com/v2/persons'
    )
  })

  it('throws on non-2xx response from deals endpoint', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ success: true, data: { id: 111, name: 'Acme Inc' } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ success: true, data: { id: 222, name: 'John Doe', org_id: 111 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ error: 'conflict' }, 409)
      }
      return jsonResponse({}, 201)
    })

    await expect(handle(basePayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Pipedrive API error: 409 Conflict for https://api.pipedrive.com/v2/deals'
    )
  })

  it('throws when event_type is not form_response', async () => {
    const payload = { ...basePayload, event_type: 'form_validation' }
    const { fetch } = fakeFetch(() => jsonResponse({}, 201))
    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      "Unsupported event type: form_validation. Expected 'form_response'"
    )
  })

  it('uses default field IDs when not provided in config', async () => {
    const config: ConnectorConfig = { pipedriveApiToken: 'test-token' }
    const payload = SOURCE_EXAMPLE as unknown as TypeformWebhookPayload

    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.pipedrive.com/v2/organizations') {
        return jsonResponse({ success: true, data: { id: 111, name: 'Acme Corp' } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/persons') {
        return jsonResponse({ success: true, data: { id: 222, name: 'Laura', org_id: 111 } }, 201)
      }
      if (req.url === 'https://api.pipedrive.com/v2/deals') {
        return jsonResponse({ success: true, data: { id: 333, title: 'Build a website', person_id: 222 } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const result = await handle(payload, { ...config, fetch })
    expect(result).toEqual({ organizationId: 111, personId: 222, dealId: 333 })
    expect(calls).toHaveLength(3)
  })
})

